function ocDetectDsh(found) {
  const root = ocPath.join(ocOs.homedir(), ".dsh");
  if (!ocFs.existsSync(root)) return;
  const refs = ocYaml(ocReadText(ocPath.join(root, ".credentials.yaml")))?.refs || {};
  let profiles = [];
  try { profiles = ocFs.readdirSync(ocPath.join(root, "profiles")).filter((d) => !/backup|test/i.test(d)); } catch {}
  profiles.sort((a, b) => (a === "desktop" ? -1 : b === "desktop" ? 1 : a.localeCompare(b)));
  const seen = new Set();
  for (const prof of profiles) {
    const doc = ocYaml(ocReadText(ocPath.join(root, "profiles", prof, "cordis.patch.yml")));
    for (const item of Array.isArray(doc) ? doc : [doc]) {
      const providers = item?.config?.providers;
      if (!providers || typeof providers !== "object") continue;
      for (const [pid, p] of Object.entries(providers)) {
        const base = p?.baseURL || p?.baseUrl || p?.base_url;
        if (!base || seen.has(pid)) continue;
        seen.add(pid);
        const auth = String(p?.headers?.Authorization || p?.headers?.authorization || "").replace(/^Bearer\s+/i, "");
        const apiKey = (p.apiKeyEnv && (refs[p.apiKeyEnv] || process.env[p.apiKeyEnv])) || p.apiKey || auth || "";
        found.push({ source: "DeepSeek Harness", app: "dsh", name: "DSH · " + (p.displayName || pid), baseUrl: ocFixBase(base), models: ocModelsOf(p), protocol: ocDshProtocol(p.api), modelMeta: ocDshModelMeta(p), apiKey: String(apiKey), note: prof === "desktop" ? "" : "配置 " + prof });
      }
    }
  }
}
