async function ocMarkDuplicates(context, items) {
  // OpenCode: 只把已导入过的配置（同名同地址）标为「已导入」；不同软件的相同地址不再标「已存在」
  const list = ocLoadProviders(context);
  for (const f of items) {
    if (f.unreadable) continue;
    const base = ocNormalizeBaseUrl(f.baseUrl);
    if (list.some((p) => p.name === f.name && p.baseUrl === base)) f.done = true;
  }
}

