var OC_VEC_JS = "/* oc-unified-ui-v2: 矢量图标——把界面里的符号字符换成 codicon 风格的线性 SVG（不碰输入框与代码） */\n(()=>{const P={add:'<path d=\"M8 3v10M3 8h10\"/>',close:'<path d=\"M4 4l8 8M12 4l-8 8\"/>',down:'<path d=\"M4.5 6.5L8 10l3.5-3.5\"/>',up:'<path d=\"M4.5 9.5L8 6l3.5 3.5\"/>',right:'<path d=\"M6.5 4.5L10 8l-3.5 3.5\"/>',check:'<path d=\"M3 8.5l3 3 7-7\"/>',star:'<path d=\"M8 2l1.8 3.8 4.2.5-3.1 2.9.8 4.1L8 11.3 4.3 13.3l.8-4.1L2 6.3l4.2-.5z\"/>',search:'<circle cx=\"7\" cy=\"7\" r=\"4.5\"/><path d=\"M10.5 10.5l3 3\"/>',ext:'<path d=\"M9 3h4v4M13 3L7.5 8.5M11 9.5V13H3V5h3.5\"/>'};\nconst MAP={'＋':'add','✕':'close','▾':'down','▴':'up','▸':'right','✓':'check','★':'star','⌕':'search','↗':'ext'};const RE=/(＋|✕|▾|▴|▸|✓|★|⌕|↗)/u;\nconst SKIP='textarea,input,select,option,script,style,svg,pre,code,.no-vec';\nconst icon=n=>{const s=document.createElement('span');s.className='oc-vi oc-vi-'+n;s.setAttribute('aria-hidden','true');s.innerHTML='<svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\">'+P[n]+'</svg>';return s};\nconst fix=root=>{const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>RE.test(n.nodeValue)&&!(n.parentElement&&n.parentElement.closest(SKIP))?1:2});const ns=[];while(w.nextNode())ns.push(w.currentNode);\nfor(const node of ns){let t=node.nodeValue;const f=document.createDocumentFragment();let m;while((m=t.match(RE))){const b=t.slice(0,m.index).replace(/\\s+$/,'');if(b)f.append(b+' ');f.append(icon(MAP[m[1]]));t=t.slice(m.index+m[0].length).replace(/^\\s+/,'');if(t)t=' '+t}if(t)f.append(t);node.replaceWith(f)}};\nlet q=false;const run=()=>{q=false;fix(document.body)};const start=()=>{run();new MutationObserver(()=>{if(!q){q=true;requestAnimationFrame(run)}}).observe(document.body,{childList:true,subtree:true,characterData:true})};\nif(document.body)start();else document.addEventListener('DOMContentLoaded',start)})();";
