    "$('#list').addEventListener('click',e=>{const r=e.target.closest('.row');if(!r)return;act=Number(r.dataset.i);mark();toggle(act);});" +
    "$('#list').addEventListener('dblclick',e=>{const r=e.target.closest('.row');if(!r)return;const it=rows[Number(r.dataset.i)];if(it&&!it.action){sel.delete(it.key);vs.postMessage({type:'add',items:[...sel.values(),it.item]});}});" +
    "$('#add').onclick=addSel;$('#cancel').onclick=()=>vs.postMessage({type:'close'});" +
    "render();$('#q').focus();vs.postMessage({type:'ready'});";
  panel.webview.html = '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; font-src ' + panel.webview.cspSource + "; style-src 'nonce-" + n + "'; script-src 'nonce-" + n + "';\"><style nonce=\"" + n + '">' + css + "</style><title>添加上下文</title></head><body>" +
    '<div class="wrap"><div class="top"><label class="sb"><i class="ci">' + String.fromCharCode(OC_CTX_CI.search) + '</i><input id="q" type="text" spellcheck="false" autocomplete="off" placeholder="搜索文件、符号、问题、终端" aria-label="搜索上下文"></label></div>' +
    '<div id="list" class="list" tabindex="0" role="listbox" aria-multiselectable="true"></div>' +
    '<div class="ft"><span id="cnt" class="c">未选择</span><span class="k"><kbd>↑</kbd><kbd>↓</kbd> 移动 · <kbd>空格</kbd> 勾选 · <kbd>Enter</kbd> 添加 · <kbd>Esc</kbd> 关闭</span><button id="cancel" class="s">取消</button><button id="add" class="p" disabled>添加</button></div></div>' +
    '<script nonce="' + n + '">' + script + "</script></body></html>";
