window.addEventListener("message",e=>{const d=e.data;if(d.type==="state"){S=d.skills||[];SRC=d.sources||[];ON=d.enabled!==false;ws=!!d.hasWorkspace;r();}if(d.type==="saved"){toast("已创建，写好正文后下一轮对话生效");hide();}if(d.type==="error"){$("#ferr").textContent=d.text;toast(d.text);}if(d.type==="toast")toast(d.text);});
$("#q").addEventListener("input",r);$("#rf").onclick=()=>vs.postMessage({type:"refresh"});$("#dir").onclick=()=>vs.postMessage({type:"openDir"});$("#mkt").onclick=()=>vs.postMessage({type:"market"});
$("#add").onclick=show;$("#cancel").onclick=hide;$("#save").onclick=()=>vs.postMessage({type:"create",name:$("#fName").value.trim(),scope:$("#fScope").value,description:$("#fDesc").value.trim()});
